var i=275;var n=`275-recipe-documentation-and-reproducibility`;var r=`262`;var s={en:`Recipe Documentation and Reproducibility`,ua:`Документування рецептів та відтворюваність результатів`};var a={short:`Clear recipe documentation turns tacit kitchen knowledge into instructions that another cook can reproduce. It records ingredients, preparation state, timing, equipment, measurable checkpoints, yield, and version history.`,sections:[{title:`Core idea`,text:`A recipe is an executable production document. “Cook until ready” is less reproducible than specifying pan temperature, visual cues, internal temperature where relevant, and the approximate time under stated conditions.`},{title:`Scientific / practical principles`,text:`Differences in measurement units, ingredient brands, equipment, and interpretation create variation. Objective parameters plus sensory endpoints make a document flexible enough for real ingredients yet comparable between cooks.`},{title:`How to apply it`,text:`Use a standard template: title, version, date, portions, ingredients by weight, allergen notes, equipment, preparation, numbered steps, time/temperature checkpoints, expected yield, storage, and test results. Record why each revision was approved.`},{title:`Practical example`,text:`A soup recipe specifies 1.0 kg trimmed carrots, pot size, diced dimensions, simmer range, blended target consistency, final mass, and a tasting note. A new team member can repeat it with less guessing.`},{title:`Common mistakes and limitations`,text:`Missing ingredient state (raw vs cooked, peeled vs whole) corrupts quantities. A photo alone is not a recipe; documented procedures still need retraining when suppliers and equipment change.`},{title:`Related theories`,text:`004, 006, 007, 266, 270, 271, 286.`},{title:`Hands-on exercise`,text:`Write a recipe card for a 4-portion soup using ingredient masses in grams, prepared yield, exact equipment, times, texture checkpoints and cooling instructions. Ask a second cook to reproduce it without spoken hints and log all uncertainties.`}]};var o={short:`Чітка документація перетворює неформальні кухарські навички на інструкції, які може повторити інша людина. У ній фіксують інгредієнти, їхній стан, час, обладнання, вимірювані контрольні точки, вихід і історію версій.`,sections:[{title:`Головна ідея`,text:`Рецепт є документом для відтворюваного виробництва. Формулювання «готуйте до готовності» менш точне, ніж орієнтири температури, кольору, консистенції та приблизного часу за заданих умов.`},{title:`Наукові та практичні принципи`,text:`Різні одиниці виміру, партії продуктів, обладнання й тлумачення змінюють результат. Числові критерії разом з органолептичними ознаками дозволяють порівнювати приготування.`},{title:`Як застосовувати`,text:`Використовуйте шаблон: назва, версія, дата, порції, маса інгредієнтів, алергени, обладнання, підготовка, кроки, температура, час, вихід, зберігання й результати тестів. Записуйте причину кожної зміни.`},{title:`Практичний приклад`,text:`Рецепт супу вказує 1 кг очищеної моркви, розмір кубиків, місткість каструлі, режим томління, бажану густину пюре та масу готової страви. Інший кухар може повторити процес.`},{title:`Поширені помилки та обмеження`,text:`Якщо не написано «сирий», «очищений» або «готовий», кількості легко сплутати. Фото не замінює технологічної карти; зміну обладнання потрібно перевіряти.`},{title:`Пов’язані теорії`,text:`004, 006, 007, 266, 270, 271, 286.`},{title:`Практична вправа`,text:`Створіть технологічну картку супу на 4 порції: маси в грамах, вихід, обладнання, час, контроль текстури та правила охолодження. Попросіть іншого кухаря повторити рецепт без усних підказок і зафіксуйте всі неоднозначності.`}]};var c=[4,6,7,266,270,271,286];var d=`Sources / Джерела`;var p=[`https://foodbuyingguide.fns.usda.gov/Home/About`,`https://www.cacfp.org/2024/07/02/recipe-standardization-guide/`,`https://theicn.org/cicn/usda-recipe-standardization-guide-for-school-nutrition-programs/`,`https://www.kingarthurbaking.com/recipes/resources/recipe-success-guide`];var l={id:275,slug:n,group:`262`,title:s,en:a,ua:o,related:c,referenceTitle:d,references:p};export{l as default,a as en,r as group,i as id,d as referenceTitle,p as references,c as related,n as slug,s as title,o as ua};